'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{spawnSync}=require('node:child_process');
const root=process.env.PUBLIC_TEST_TMP_ROOT||process.env.RUNNER_TEMP;assert(root&&fs.existsSync(root));
function copy(){const d=fs.mkdtempSync(path.join(root,'cleanup-custody-'));for(const n of ['index.cjs','producer-schema.cjs','cleanup-schema.cjs','cleanup-backend.cjs','cleanup-worker.cjs'])fs.copyFileSync(path.join(__dirname,n),path.join(d,n));return d;}
function run(code){return spawnSync(process.execPath,['-e',code],{encoding:'utf8',env:{PATH:process.env.PATH},timeout:21000});}
test('substituted helper is rejected before its top-level code or fixed child',()=>{const d=copy(),marker=path.join(d,'BAD');fs.writeFileSync(path.join(d,'cleanup-worker.cjs'),`require('node:fs').writeFileSync(${JSON.stringify(marker)},'BAD')`);const p=run(`try{require(${JSON.stringify(path.join(d,'index.cjs'))});process.exit(2);}catch{process.exit(0)}`);assert.equal(p.status,0);assert(!fs.existsSync(marker));});
test('post-capture pathname swap cannot replace worker bytes passed through sealed source channel',()=>{const d=copy(),marker=path.join(d,'BAD');const code=`const fs=require('node:fs'),i=require(${JSON.stringify(path.join(d,'index.cjs'))});fs.writeFileSync(${JSON.stringify(path.join(d,'cleanup-worker.cjs'))},${JSON.stringify(`require('node:fs').writeFileSync(${JSON.stringify(marker)},'BAD');module.exports.run=async()=>{}`)});i.phaseWorker({request:{command:'READ_TARGET'},context:null,bundle:null,current_records:[]},{}).then(()=>process.exit(2),()=>process.exit(0));`;const p=run(code);assert.equal(p.status,0);assert(!fs.existsSync(marker));});
test('worker closed native routes and raw transport failures never emit credential text',()=>{
 const code=`const https=require('node:https'),{EventEmitter}=require('node:events'),fs=require('node:fs');let count=0;https.request=(options,cb)=>{count++;if(options.hostname!=='api.github.com'||options.method!=='GET')throw new Error('BAD_ROUTE');const q=new EventEmitter();q.setTimeout=()=>{};q.destroy=()=>{};q.end=()=>queueMicrotask(()=>{const r=new EventEmitter();r.statusCode=302;r.destroy=()=>{};cb(r);r.emit('data',Buffer.from('PUBLIC_SYNTHETIC_SECRET'));r.emit('end');});return q;};const w=require(${JSON.stringify(path.join(__dirname,'cleanup-worker.cjs'))});const client=w.nativeClient('PUBLIC_EPHEMERAL');(async()=>{let held=false;try{await client('repos/Borduas-Holdings/Blazing-Back/actions/runs/123');}catch(e){held=e.message==='CLEANUP_NATIVE_HOLD';}let refused=false;try{client('https://foreign.invalid/token');}catch{refused=true;}console.log('PUBLIC_SYNTHETIC_SECRET');console.error('PUBLIC_SYNTHETIC_SECRET');fs.writeSync(1,JSON.stringify({held,refused,count}));})().catch(()=>process.exit(1));`;
 const p=run(code);assert.equal(p.status,0);assert.deepEqual(JSON.parse(p.stdout),{held:true,refused:true,count:1});assert(!p.stderr.includes('PUBLIC_SYNTHETIC_SECRET'));
});
test('worker native counter is bounded independently of official immutable artifact transport retries',()=>{
 const code=`const https=require('node:https'),{EventEmitter}=require('node:events'),fs=require('node:fs');let count=0;https.request=(o,cb)=>{count++;const q=new EventEmitter();q.setTimeout=()=>{};q.destroy=()=>{};q.end=()=>queueMicrotask(()=>{const r=new EventEmitter();r.statusCode=200;r.destroy=()=>{};cb(r);r.emit('data',Buffer.from('{}'));r.emit('end');});return q;};const w=require(${JSON.stringify(path.join(__dirname,'cleanup-worker.cjs'))});const client=w.nativeClient('PUBLIC_NONAUTH');(async()=>{for(let n=0;n<60;n++)await client('repos/Borduas-Holdings/Blazing-Back/actions/runs/123');let held=false;try{client('repos/Borduas-Holdings/Blazing-Back/actions/runs/123');}catch{held=true;}fs.writeSync(1,JSON.stringify({held,count}));})().catch(()=>process.exit(1));`;
 const p=run(code);assert.equal(p.status,0);assert.deepEqual(JSON.parse(p.stdout),{held:true,count:60});
});
